import type { ProjectRecord } from '#/server/projects.server'

const record = (): ProjectRecord => ({
  id: 'p1',
  name: 'Test',
  data: defaultProjectData(),
  revision: 3,
  createdAt: '2026-01-01T00:00:00.000Z',
  updatedAt: '2026-01-01T00:00:00.000Z',
  view: { llSim: { step: 0, speed: 1 } },
})

const setInput = (input: string) => (d: ProjectData) => ({ ...d, ll: { ...d.ll, input } })

function setup(initial = record()) {
  const fake = createFakeTransport(initial)
  const session = createProjectSession(initial, fake.transport)
  return { fake, session, state: () => session.getState() }
}

beforeEach(() => vi.useFakeTimers())
afterEach(() => vi.useRealTimers())

describe('autosave', () => {
  it('notifies subscribers of every state change', async () => {
    const { session } = setup()
    const seen: string[] = []
    const unsubscribe = session.subscribe(() => {
      const status = session.getState().status
      if (seen.at(-1) !== status) seen.push(status)
    })
    session.edit(setInput('a'))
    await vi.advanceTimersByTimeAsync(600)
    unsubscribe()
    session.edit(setInput('b'))
    expect(seen).toEqual(['pending', 'saving', 'saved'])
  })

  it('saves an edit after the debounce and reports it saved', async () => {
    const { fake, session, state } = setup()
    session.edit(setInput('id + id'))
    expect(state().status).toBe('pending')
    expect(fake.callsOf('save')).toHaveLength(0)

    await vi.advanceTimersByTimeAsync(600)

    expect(fake.server.record?.data.ll.input).toBe('id + id')
    expect(fake.server.record?.revision).toBe(4)
    expect(state().status).toBe('saved')
    expect(state().unsaved).toBe(false)
  })

  it('saves edits made while a save is in flight afterwards, one request at a time', async () => {
    const { fake, session, state } = setup()
    fake.hold()
    session.edit(setInput('a'))
    await vi.advanceTimersByTimeAsync(600)
    expect(state().status).toBe('saving')

    session.edit(setInput('ab'))
    await vi.advanceTimersByTimeAsync(600)
    expect(fake.callsOf('save')).toHaveLength(1)

    fake.release()
    await vi.advanceTimersByTimeAsync(600)

    expect(fake.callsOf('save')).toHaveLength(2)
    expect(fake.server.record?.data.ll.input).toBe('ab')
    expect(fake.server.record?.revision).toBe(5)
    expect(state().status).toBe('saved')
  })
})

