describe('save errors (bug 2)', () => {
  it('retries transient failures with growing delays and recovers', async () => {
    const { fake, session, state } = setup()
    fake.failWith(new TransportError('Failed to fetch', true))
    session.edit(setInput('x'))
    await vi.advanceTimersByTimeAsync(600)
    expect(state().status).toBe('retrying')
    expect(state().unsaved).toBe(true)

    await vi.advanceTimersByTimeAsync(5_000)
    expect(fake.callsOf('save')).toHaveLength(2)
    await vi.advanceTimersByTimeAsync(5_000)
    expect(fake.callsOf('save')).toHaveLength(2) // second delay is longer
    await vi.advanceTimersByTimeAsync(5_000)
    expect(fake.callsOf('save')).toHaveLength(3)

    fake.failWith(null)
    await vi.advanceTimersByTimeAsync(20_000)
    expect(state().status).toBe('saved')
    expect(fake.server.record?.data.ll.input).toBe('x')
  })

  it('surfaces a rejected save with its message and gives up after a few attempts', async () => {
    const { fake, session, state } = setup()
    fake.failWith(new TransportError('Projekt je príliš veľký', false))
    session.edit(setInput('huge'))
    await vi.advanceTimersByTimeAsync(600)
    expect(state().status).toBe('failed')
    expect(state().error).toBe('Projekt je príliš veľký')

    await vi.advanceTimersByTimeAsync(10 * 60_000)
    expect(fake.callsOf('save')).toHaveLength(3)
    expect(state().status).toBe('failed')
    expect(state().data.ll.input).toBe('huge')

    // A new edit is a new attempt (it may have fixed the problem).
    fake.failWith(null)
    session.edit(setInput('small'))
    await vi.advanceTimersByTimeAsync(600)
    expect(state().status).toBe('saved')
    expect(state().error).toBeNull()
  })
})

describe('conflicts', () => {
  async function conflicted() {
    const s = setup()
    s.fake.externalSave(setInput('theirs')(record().data))
    s.session.edit(setInput('mine'))
    await vi.advanceTimersByTimeAsync(600)
    return s
  }

  it('stops saving and keeps local edits when another tab saved first', async () => {
    const { fake, session, state } = await conflicted()
    expect(state().status).toBe('conflict')
    expect(state().conflict?.data.ll.input).toBe('theirs')
    expect(state().data.ll.input).toBe('mine')

    session.edit(setInput('mine 2'))
    await vi.advanceTimersByTimeAsync(60_000)
    expect(fake.callsOf('save')).toHaveLength(1)
  })

  it("'theirs' adopts the server version", async () => {
    const { fake, session, state } = await conflicted()
    session.resolveConflict('theirs')
    expect(state().data.ll.input).toBe('theirs')
    expect(state().conflict).toBeNull()
    expect(state().status).toBe('saved')
    expect(state().unsaved).toBe(false)

    session.edit(setInput('theirs + more'))
    await vi.advanceTimersByTimeAsync(600)
    expect(fake.server.record?.data.ll.input).toBe('theirs + more')
    expect(state().status).toBe('saved')
  })

  it("'mine' overwrites the server version", async () => {
    const { fake, session, state } = await conflicted()
    await session.resolveConflict('mine')
    expect(fake.server.record?.data.ll.input).toBe('mine')
    expect(state().conflict).toBeNull()
    expect(state().status).toBe('saved')
  })
})

describe('operations that replace the document (bug 3)', () => {
  it('restoreVersion saves pending edits first, then adopts the restored version', async () => {
    const { fake, session, state } = setup()
    fake.server.snapshots.push({ id: 1, label: 'old', data: setInput('old')(record().data) })
    session.edit(setInput('unsaved work'))

    await session.restoreVersion(1)

    // The work reached the server before the restore, so the server's pre-restore snapshot has it.
    expect(fake.calls.map((c) => c.op)).toEqual(['save', 'restore'])
    expect(fake.server.snapshots.at(-1)?.data.ll.input).toBe('unsaved work')
    expect(state().data.ll.input).toBe('old')
    expect(state().status).toBe('saved')

    session.edit(setInput('old + more'))
    await vi.advanceTimersByTimeAsync(600)
    expect(state().status).toBe('saved')
    expect(fake.server.record?.data.ll.input).toBe('old + more')
  })

  it('importData replaces the document with the imported data', async () => {
    const { fake, session, state } = setup()
    await session.importData(setInput('imported')(record().data), 'Pred importom a.json')
    expect(fake.callsOf('replace')[0].input).toMatchObject({ id: 'p1', label: 'Pred importom a.json' })
    expect(state().data.ll.input).toBe('imported')
  })

  it('saveNamedVersion saves pending edits first', async () => {
    const { fake, session } = setup()
    session.edit(setInput('keep me'))
    await session.saveNamedVersion('v1')
    expect(fake.server.snapshots.at(-1)).toMatchObject({ label: 'v1', data: { ll: { input: 'keep me' } } })
  })

  it('refuses during a conflict and keeps local edits', async () => {
    const { fake, session, state } = setup()
    fake.server.snapshots.push({ id: 1, label: 'old', data: record().data })
    fake.externalSave(setInput('theirs')(record().data))
    session.edit(setInput('mine'))
    await vi.advanceTimersByTimeAsync(600)

    await expect(session.restoreVersion(1)).rejects.toThrow(/konflikt/i)
    await expect(session.importData(record().data, 'x')).rejects.toThrow(/konflikt/i)
    await expect(session.saveNamedVersion('v')).rejects.toThrow(/konflikt/i)
    expect(fake.callsOf('restore')).toHaveLength(0)
    expect(fake.callsOf('replace')).toHaveLength(0)
    expect(fake.callsOf('createSnapshot')).toHaveLength(0)
    expect(state().data.ll.input).toBe('mine')
  })

  it('refuses when local edits cannot be saved, with the reason', async () => {
    const { fake, session, state } = setup()
    fake.server.snapshots.push({ id: 1, label: 'old', data: record().data })
    fake.failWith(new TransportError('Failed to fetch', true))
    session.edit(setInput('mine'))

    await expect(session.restoreVersion(1)).rejects.toThrow(/neuložené zmeny.*Failed to fetch/i)
    await expect(session.saveNamedVersion('v')).rejects.toThrow(/neuložené zmeny/i)
    expect(fake.callsOf('restore')).toHaveLength(0)
    expect(fake.callsOf('createSnapshot')).toHaveLength(0)
    expect(state().data.ll.input).toBe('mine')
  })

  it('refuses when the project was deleted', async () => {
    const { fake, session } = setup()
    fake.deleteProject()
    session.edit(setInput('mine'))
    await expect(session.importData(record().data, 'x')).rejects.toThrow(/zmazaný/i)
    expect(fake.callsOf('replace')).toHaveLength(0)
  })

  it('reports a snapshot that no longer exists', async () => {
    const { session } = setup()
    await expect(session.restoreVersion(42)).rejects.toThrow('Verzia už neexistuje')
  })
})

describe('serialization with saves in flight (bug 4)', () => {
  it('a restore waits for the save in flight and adopts without a self-conflict', async () => {
    const { fake, session, state } = setup()
    fake.server.snapshots.push({ id: 1, label: 'old', data: setInput('old')(record().data) })
    fake.hold()
    session.edit(setInput('typing'))
    await vi.advanceTimersByTimeAsync(600) // save in flight

    const restoring = session.restoreVersion(1)
    await vi.advanceTimersByTimeAsync(0)
    expect(fake.callsOf('restore')).toHaveLength(0)

    fake.release()
    await restoring
    expect(fake.calls.map((c) => c.op)).toEqual(['save', 'restore'])
    expect(state().data.ll.input).toBe('old')
    expect(state().status).toBe('saved')

    session.edit(setInput('old!'))
    await vi.advanceTimersByTimeAsync(600)
    expect(state().status).toBe('saved')
    expect(fake.server.record?.data.ll.input).toBe('old!')
  })

  it('edits made while a restore is running are kept as a conflict, not dropped', async () => {
    const { fake, session, state } = setup()
    fake.server.snapshots.push({ id: 1, label: 'old', data: setInput('old')(record().data) })
    fake.hold()
    const restoring = session.restoreVersion(1)
    await vi.advanceTimersByTimeAsync(0)
    session.edit(setInput('typed during restore'))
    await vi.advanceTimersByTimeAsync(600)
    expect(fake.callsOf('save')).toHaveLength(0)

    fake.release()
    await restoring
    expect(state().status).toBe('conflict')
    expect(state().data.ll.input).toBe('typed during restore')
    expect(state().conflict?.data.ll.input).toBe('old')
  })
})

describe('leaving and coming back (bug 5)', () => {
  it('dispose saves pending edits right away and the loader can wait for them', async () => {
    const { fake, session } = setup()
    fake.hold()
    session.edit(setInput('last keystroke'))
    session.dispose()

    let settled = false
    const waiting = savesSettled('p1').then(() => (settled = true))
    await vi.advanceTimersByTimeAsync(0)
    expect(fake.callsOf('save')).toHaveLength(1)
    expect(settled).toBe(false)

    fake.release()
    await waiting
    expect(fake.server.record?.data.ll.input).toBe('last keystroke')
    await expect(savesSettled('other')).resolves.toBeUndefined()
  })

  it('a session resumed after dispose (effects re-run) keeps autosaving', async () => {
    const { fake, session, state } = setup()
    session.dispose()
    session.resume()
    session.edit(setInput('again'))
    await vi.advanceTimersByTimeAsync(600)
    expect(fake.server.record?.data.ll.input).toBe('again')
    expect(state().status).toBe('saved')
  })

  it('adopts a newer record from the loader when nothing is pending', () => {
    const { session, state } = setup()
    session.receive({ ...record(), revision: 7, data: setInput('newer')(record().data) })
    expect(state().data.ll.input).toBe('newer')
    session.receive({ ...record(), revision: 5, data: setInput('older')(record().data) })
    expect(state().data.ll.input).toBe('newer')
  })

  it('ignores a newer loader record while local edits are unsaved', () => {
    const { session, state } = setup()
    session.edit(setInput('mine'))
    session.receive({ ...record(), revision: 7, data: setInput('newer')(record().data) })
    expect(state().data.ll.input).toBe('mine')
  })
})

describe('view state', () => {
  const step = (n: number) => (v: { llSim: { step: number; speed: number } }) => ({ ...v, llSim: { ...v.llSim, step: n } })

  it('is saved debounced on its own, without touching the document revision', async () => {
    const { fake, session, state } = setup()
    session.updateView(step(4))
    expect(state().view.llSim.step).toBe(4)
    // View state never arms the leave-page prompt; only document edits do.
    expect(state().unsaved).toBe(false)

    await vi.advanceTimersByTimeAsync(600)
    expect(fake.callsOf('saveView')).toHaveLength(1)
    expect(fake.server.view.llSim.step).toBe(4)
    expect(fake.callsOf('save')).toHaveLength(0)
    expect(state().unsaved).toBe(false)
    expect(state().status).toBe('saved')
  })

  it('is still saved during a document conflict', async () => {
    const { fake, session } = setup()
    fake.externalSave(setInput('theirs')(record().data))
    session.edit(setInput('mine'))
    await vi.advanceTimersByTimeAsync(600)
    session.updateView(step(2))
    await vi.advanceTimersByTimeAsync(600)
    expect(fake.server.view.llSim.step).toBe(2)
  })

  it('retries a transient failure', async () => {
    const { fake, session, state } = setup()
    fake.failWith(new TransportError('Failed to fetch', true))
    session.updateView(step(1))
    await vi.advanceTimersByTimeAsync(600)
    fake.failWith(null)
    await vi.advanceTimersByTimeAsync(5_000)
    expect(fake.server.view.llSim.step).toBe(1)
    expect(state().unsaved).toBe(false)
  })

  it('is flushed on dispose', async () => {
    const { fake, session } = setup()
    session.updateView(step(9))
    session.dispose()
    await savesSettled('p1')
    expect(fake.server.view.llSim.step).toBe(9)
  })
})

describe('page hidden (bug 6)', () => {
  it('flushes document and view right away, asking the transport to outlive the page', async () => {
    const { fake, session } = setup()
    session.edit(setInput('closing'))
    session.updateView((v) => ({ ...v, llSim: { ...v.llSim, step: 3 } }))
    session.pageHidden()
    await vi.advanceTimersByTimeAsync(0)
    expect(fake.callsOf('save')[0].opts).toEqual({ keepalive: true })
    expect(fake.callsOf('saveView')[0].opts).toEqual({ keepalive: true })
    expect(fake.server.record?.data.ll.input).toBe('closing')
  })
})
